// Ingram Ltd - index page
// Data comes from data/bdc2.js (generated by export_data.py from the Excel model).

(function () {
  "use strict";

  var data = window.BDC2;
  document.getElementById("year").textContent = new Date().getFullYear();
  setupModal();
  setupTabs();

  if (!data || !data.series || !data.series.length) {
    document.getElementById("keyStats").innerHTML = "<div><dt>Data unavailable</dt><dd>-</dd></div>";
    return;
  }

  var series = data.series;
  var stats = data.stats;
  var last = series[series.length - 1];
  var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  function fmtPct(x, dp) {
    if (x === null || x === undefined || isNaN(x)) return "-";
    return (x * 100).toFixed(dp === undefined ? 2 : dp);
  }
  function fmtNum(x, dp) {
    return x.toLocaleString("en-GB", { minimumFractionDigits: dp, maximumFractionDigits: dp });
  }
  function fmtDate(iso) {
    var d = new Date(iso + "T00:00:00");
    return d.getDate() + " " + MONTHS[d.getMonth()] + " " + d.getFullYear();
  }
  function negClass(x) { return x < 0 ? ' class="neg"' : ""; }

  // level n months before the latest observation (null if not available)
  function levelBack(n) {
    var i = series.length - 1 - n;
    return i >= 0 ? series[i].level : null;
  }
  function ret(n) {
    var start = levelBack(n);
    return start ? last.level / start - 1 : null;
  }
  function annualise(cum, months) {
    return cum === null ? null : Math.pow(1 + cum, 12 / months) - 1;
  }

  var lastYear = Number(last.date.slice(0, 4));
  var decPrev = series.filter(function (p) { return p.date.slice(0, 7) === (lastYear - 1) + "-12"; })[0];
  var ytd = decPrev ? last.level / decPrev.level - 1 : null;
  var siMonths = series.length - 1;
  var siCum = last.level / series[0].level - 1;

  // Key stats
  var keyStats = [
    ["Index level", fmtNum(last.level, 2)],
    ["1 month", fmtPct(ret(1)) + "%"],
    ["Year to date", fmtPct(ytd) + "%"],
    ["1 year", fmtPct(ret(12)) + "%"],
    ["Since inception (ann.)", fmtPct(annualise(siCum, siMonths)) + "%"]
  ];
  document.getElementById("keyStats").innerHTML = keyStats.map(function (s) {
    return "<div><dt>" + s[0] + "</dt><dd>" + s[1] + "</dd></div>";
  }).join("");
  document.getElementById("asOfTop").textContent = "As of " + fmtDate(last.date) + ". Total return, USD.";
  document.getElementById("asOfCons").textContent = "As of " + fmtDate(last.date);
  document.getElementById("factBase").textContent = "1,000 on " + fmtDate(data.base.date);
  document.getElementById("factCount").textContent = data.constituents.length;

  // Period returns
  var periods = [["1m", 1], ["3m", 3], ["6m", 6], ["YTD", null], ["1y", 12], ["3y", 36], ["Since inception", siMonths]];
  var head = "<thead><tr><th></th>" + periods.map(function (p) { return "<th>" + p[0] + "</th>"; }).join("") + "</tr></thead>";
  var cumRow = "<tr><th scope='row'>Cumulative</th>";
  var annRow = "<tr><th scope='row'>Annualised</th>";
  periods.forEach(function (p) {
    var c = p[1] === null ? ytd : (p[0] === "Since inception" ? siCum : ret(p[1]));
    cumRow += "<td" + negClass(c) + ">" + fmtPct(c) + "</td>";
    var a = (p[1] && p[1] >= 12) ? annualise(c, p[1]) : null;
    annRow += "<td" + (a !== null ? negClass(a) : "") + ">" + fmtPct(a) + "</td>";
  });
  document.getElementById("periodTable").innerHTML = head + "<tbody>" + cumRow + "</tr>" + annRow + "</tr></tbody>";

  // Calendar years and monthly grid
  var byMonth = {};
  series.forEach(function (p) { byMonth[p.date.slice(0, 7)] = p; });
  var years = [];
  series.forEach(function (p) { var y = p.date.slice(0, 4); if (years.indexOf(y) === -1) years.push(y); });
  years.reverse();

  var yearRows = "";
  var monthRows = "";
  years.forEach(function (y) {
    var pts = series.filter(function (p) { return p.date.slice(0, 4) === y; });
    var start = byMonth[(Number(y) - 1) + "-12"] || series[0];
    var r = pts[pts.length - 1].level / start.level - 1;
    var label = y;
    if (!byMonth[(Number(y) - 1) + "-12"]) label += "*";
    if (Number(y) === lastYear && last.date.slice(5, 7) !== "12") label += " YTD";
    yearRows += "<tr><th scope='row'>" + label + "</th><td" + negClass(r) + ">" + fmtPct(r) + "</td></tr>";

    monthRows += "<tr><th scope='row'>" + y + "</th>";
    for (var m = 1; m <= 12; m++) {
      var p = byMonth[y + "-" + (m < 10 ? "0" + m : m)];
      var v = p && p.ret !== null ? p.ret : null;
      monthRows += v === null ? "<td></td>" : "<td" + negClass(v) + ">" + fmtPct(v) + "</td>";
    }
    monthRows += "<td" + negClass(r) + "><strong>" + fmtPct(r) + "</strong></td></tr>";
  });
  document.getElementById("yearTable").innerHTML = "<thead><tr><th>Year</th><th>Index</th></tr></thead><tbody>" + yearRows + "</tbody>";
  document.getElementById("monthTable").innerHTML = "<thead><tr><th></th>" + MONTHS.map(function (m) { return "<th>" + m + "</th>"; }).join("") + "<th>Year</th></tr></thead><tbody>" + monthRows + "</tbody>";

  // Risk
  var seKey = Object.keys(stats).filter(function (k) { return k.indexOf("Std error") === 0; })[0];
  var riskRows = [
    ["Annualised volatility", fmtPct(stats["Annualised volatility (reported)"]), fmtPct(stats["Annualised volatility (de-smoothed)"])],
    ["Maximum drawdown", fmtPct(stats["Max drawdown (reported)"]), fmtPct(stats["Max drawdown (de-smoothed)"])],
    ["Lag-1 autocorrelation", stats["Lag-1 autocorrelation φ"].toFixed(2), "-"],
    ["Standard error of autocorrelation", seKey ? stats[seKey].toFixed(2) : "-", "-"],
    ["Number of months", String(stats["Months of data"]), String(stats["Months of data"])]
  ];
  document.getElementById("riskTable").innerHTML =
    "<thead><tr><th>Since inception</th><th>Reported</th><th>De-smoothed</th></tr></thead><tbody>" +
    riskRows.map(function (r) { return "<tr><th scope='row'>" + r[0] + "</th><td>" + r[1] + "</td><td>" + r[2] + "</td></tr>"; }).join("") +
    "</tbody>";

  // Constituents
  document.getElementById("consTable").innerHTML =
    "<thead><tr><th>Fund</th><th>Ticker</th><th style='text-align:left'>Sponsor</th><th>Weight (%)</th><th>Distribution yield (%)</th></tr></thead><tbody>" +
    data.constituents.map(function (c) {
      return "<tr><td>" + c.fund + "</td><td>" + c.code + "</td><td style='text-align:left'>" + c.sponsor + "</td><td>" + fmtPct(c.weight, 1) + "</td><td>" + fmtPct(c.yield) + "</td></tr>";
    }).join("") + "</tbody>";

  // Growth chart
  var chartEl = document.getElementById("growthChart");
  var currentRange = "all";
  drawChart();
  window.addEventListener("resize", debounce(drawChart, 150));

  Array.prototype.forEach.call(document.querySelectorAll(".range button"), function (btn) {
    btn.addEventListener("click", function () {
      document.querySelectorAll(".range button").forEach(function (b) { b.classList.remove("is-active"); });
      btn.classList.add("is-active");
      currentRange = btn.getAttribute("data-range");
      drawChart();
    });
  });

  function drawChart() {
    var pts = currentRange === "all" ? series.slice() : series.slice(Math.max(0, series.length - 1 - Number(currentRange)));
    var base = pts[0];
    var rows = pts.map(function (p) {
      return {
        date: p.date,
        idx: 10000 * p.level / base.level,
        ds: 10000 * (p.desmoothed || p.level) / (base.desmoothed || base.level)
      };
    });

    var w = chartEl.clientWidth, h = chartEl.clientHeight;
    var pad = { t: 12, r: 12, b: 28, l: 56 };
    var vals = [];
    rows.forEach(function (r) { vals.push(r.idx, r.ds); });
    var min = Math.min.apply(null, vals), max = Math.max.apply(null, vals);
    var step = niceStep((max - min) / 5);
    min = Math.floor(min / step) * step;
    max = Math.ceil(max / step) * step;

    var x = function (i) { return pad.l + (w - pad.l - pad.r) * i / (rows.length - 1); };
    var y = function (v) { return pad.t + (h - pad.t - pad.b) * (1 - (v - min) / (max - min)); };

    var svg = '<svg viewBox="0 0 ' + w + " " + h + '" role="img" aria-label="Growth of 10,000 invested in the index">';
    for (var v = min; v <= max + 0.001; v += step) {
      svg += '<line x1="' + pad.l + '" x2="' + (w - pad.r) + '" y1="' + y(v) + '" y2="' + y(v) + '" stroke="#ececec"/>';
      svg += '<text x="' + (pad.l - 8) + '" y="' + (y(v) + 4) + '" text-anchor="end" font-size="12" fill="#595959">' + fmtNum(v, 0) + "</text>";
    }
    var labelEvery = rows.length > 24 ? 12 : 3;
    rows.forEach(function (r, i) {
      var mth = Number(r.date.slice(5, 7));
      var show = labelEvery === 12 ? mth === 1 : (i % 3 === 0);
      if (show) {
        var lbl = labelEvery === 12 ? r.date.slice(0, 4) : MONTHS[mth - 1] + " " + r.date.slice(2, 4);
        svg += '<text x="' + x(i) + '" y="' + (h - 8) + '" text-anchor="middle" font-size="12" fill="#595959">' + lbl + "</text>";
      }
    });
    svg += '<path d="' + path(rows, "ds", x, y) + '" fill="none" stroke="#8c8c8c" stroke-width="1.5" stroke-dasharray="4 3"/>';
    svg += '<path d="' + path(rows, "idx", x, y) + '" fill="none" stroke="#000" stroke-width="2"/>';
    svg += '<line id="hoverLine" y1="' + pad.t + '" y2="' + (h - pad.b) + '" stroke="#000" stroke-width="1" visibility="hidden"/>';
    svg += "</svg>";
    chartEl.innerHTML = svg + '<div class="chart__tip" id="chartTip"></div>';

    var tip = document.getElementById("chartTip");
    var hl = document.getElementById("hoverLine");
    chartEl.onmousemove = function (e) {
      var rect = chartEl.getBoundingClientRect();
      var i = Math.round((e.clientX - rect.left - pad.l) / (w - pad.l - pad.r) * (rows.length - 1));
      i = Math.max(0, Math.min(rows.length - 1, i));
      hl.setAttribute("x1", x(i)); hl.setAttribute("x2", x(i)); hl.setAttribute("visibility", "visible");
      tip.innerHTML = "<strong>" + fmtDate(rows[i].date) + "</strong><br>Index: " + fmtNum(rows[i].idx, 0) + "<br>De-smoothed: " + fmtNum(rows[i].ds, 0);
      tip.style.display = "block";
      var left = x(i) + 12;
      if (left + 170 > w) left = x(i) - 180;
      tip.style.left = left + "px";
      tip.style.top = "16px";
    };
    chartEl.onmouseleave = function () { tip.style.display = "none"; hl.setAttribute("visibility", "hidden"); };
  }

  function path(rows, key, x, y) {
    return rows.map(function (r, i) { return (i ? "L" : "M") + x(i).toFixed(1) + "," + y(r[key]).toFixed(1); }).join("");
  }
  function niceStep(raw) {
    var p = Math.pow(10, Math.floor(Math.log10(raw)));
    var n = raw / p;
    return (n < 1.5 ? 1 : n < 3 ? 2 : n < 7 ? 5 : 10) * p;
  }
  function debounce(fn, ms) {
    var t;
    return function () { clearTimeout(t); t = setTimeout(fn, ms); };
  }

  // ---- page furniture ----

  function setupModal() {
    var modal = document.getElementById("investorModal");
    var accepted = false;
    try { accepted = localStorage.getItem("ingram_terms") === "1"; } catch (e) { /* storage blocked */ }
    if (!accepted) modal.hidden = false;
    document.getElementById("investorAccept").addEventListener("click", function () {
      try { localStorage.setItem("ingram_terms", "1"); } catch (e) { }
      modal.hidden = true;
    });
    document.getElementById("investorTypeBtn").addEventListener("click", function () { modal.hidden = false; });
  }

  function setupTabs() {
    var links = document.querySelectorAll(".tabs a");
    if (!("IntersectionObserver" in window)) return;
    var obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (!en.isIntersecting) return;
        links.forEach(function (l) { l.classList.toggle("is-active", l.getAttribute("href") === "#" + en.target.id); });
      });
    }, { rootMargin: "-40% 0px -55% 0px" });
    ["overview", "performance", "risk", "constituents", "methodology", "documents"].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) obs.observe(el);
    });
  }
})();
